INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q697621', 'Siege of Fort Zeelandia', 'The siege of Fort Zeelandia of 1661–1662 ended the Dutch East India Company''s rule over Taiwan and began the Kingdom of Tungning''s rule over the island.', 1661, 3, 30, 1662, 2, 1, 'day', '30 March 1661 – 1 February 1662', 59, 'https://en.wikipedia.org/wiki/Siege_of_Fort_Zeelandia'),
  ('Q276656', 'Battle of Penghu', 'The Battle of Penghu (Chinese: 澎湖海戰) was a naval battle fought in 1683 between the Qing dynasty and the Kingdom of Tungning. The Qing admiral Shi Lang led a fleet to attack the Tungning forces in Penghu.', 1683, 7, 16, NULL, NULL, NULL, 'day', '16 July 1683', 45, 'https://en.wikipedia.org/wiki/Battle_of_Penghu'),
  ('Q499468', 'Lin Shuangwen rebellion', 'The Lin Shuangwen rebellion (Chinese: 林爽文事件; Pe̍h-ōe-jī: Lîm Sóng-bûn sū-kiāⁿ; lit. ''Lin Shuangwen Incident'') occurred in 1787–1788 in Taiwan under the rule of the Qing dynasty.', 1786, NULL, NULL, 1788, NULL, NULL, 'year', '1786–1788', 34, 'https://en.wikipedia.org/wiki/Lin_Shuangwen_rebellion'),
  ('Q7675731', 'Tai Chao-chuen incident', 'The Tai Chao-chuen Incident (Chinese: 戴潮春事件) was one of the three major rebellions in Taiwan during the rule of the Qing dynasty. The rebellion lasted from 1862 to about 1865.', 1862, NULL, NULL, NULL, NULL, NULL, 'year', '1862', 26, 'https://en.wikipedia.org/wiki/Tai_Chao-chuen_incident'),
  ('Q728355', 'Battle of Tamsui', 'The Battle of Tamsui, Danshui, or Hobe (2–8 October 1884) was a significant battle where French military forces were defeated by Qing forces at Tamsui on Taiwan during the Keelung Campaign of the Sino-French War.', 1884, 10, 8, NULL, NULL, NULL, 'day', '8 October 1884', 37, 'https://en.wikipedia.org/wiki/Battle_of_Tamsui'),
  ('Q2583202', 'Pescadores Campaign', 'The Pescadores campaign (23–26 March 1895) was the last military operation of the First Sino-Japanese War and an essential preliminary to the Japanese conquest of Taiwan.', 1895, 3, 23, 1895, 3, 26, 'day', '23 March 1895 – 26 March 1895', 48, 'https://en.wikipedia.org/wiki/Pescadores_campaign_(1895)'),
  ('Q702053', '1906 Meishan earthquake', 'The 1906 Meishan earthquake (Chinese: 1906年梅山地震; pinyin: 1906 nián Měishān Dìzhèn) was centered on Moe''akhe (Chinese: 梅仔坑; Pe̍h-ōe-jī: Môe-á-kheⁿ), Kagi-cho, Japanese Taiwan (modern-day Meishan, Chiayi County, Taiwan) and occurred on March 17. Referred to at the time as the Great Kagi earthquake (Chinese: 嘉義大地震; pinyin: Jiāyì Dà Dìzhèn), it is the third-deadliest earthquake in Taiwan''s recorded history, claiming around 1,260 lives.', 1906, 3, 16, NULL, NULL, NULL, 'day', '16 March 1906', 37, 'https://en.wikipedia.org/wiki/1906_Meishan_earthquake'),
  ('Q10902675', 'Beipu Uprising', 'The Beipu Incident (Chinese: 北埔事件), or the Beipu Uprising, in 1907 was the first instance of an armed local uprising against the Japanese rule of the island of Taiwan. In response to oppression of the local population by the Japanese authorities, a group of insurgents from the Hakka subgroup of Han Chinese and Saisiyat indigenous group in Hoppo, Shinchiku Chō (modern-day Beipu, Hsinchu County), attacked Japanese officials and their families.', 1907, 11, NULL, NULL, NULL, NULL, 'month', 'November 1907', 30, 'https://en.wikipedia.org/wiki/Beipu_uprising'),
  ('Q190517', 'Xinhai Revolution', 'The 1911 Revolution, also known as the Xinhai Revolution or Hsinhai Revolution, culminated in the end of China''s last imperial dynasty, the Qing dynasty, and led to the establishment of the Republic of China (ROC). The revolution was the culmination of a decade of agitation, revolts, and uprisings.', 1911, 10, 10, 1912, 2, 12, 'day', '10 October 1911 – 12 February 1912', 81, 'https://en.wikipedia.org/wiki/1911_Revolution'),
  ('Q2427430', 'Northeast Flag Replacement', 'The Northeast Flag Replacement (traditional Chinese: 東北易幟; simplified Chinese: 东北易帜; pinyin: Dōngběi Yìzhì) refers to Zhang Xueliang''s announcement on 29 December 1928 that all banners of the Beiyang government in Manchuria would be replaced with the flag of the Nationalist government, thus nominally uniting China under one government following the Northern Expedition.', 1928, 12, 29, NULL, NULL, NULL, 'day', '29 December 1928', 55, 'https://en.wikipedia.org/wiki/Northeast_Flag_Replacement'),
  ('Q170314', 'Second Sino-Japanese War', 'The Second Sino-Japanese War was fought between the Republic of China and the Empire of Japan and its puppet states between 1937 and 1945, following a period of conflict that started in 1931. It is often regarded as the beginning of World War II in Asia, as the wars became heavily intertwined after Japan attacked the United States.', 1937, 7, 7, 1945, 9, 9, 'day', '7 July 1937 – 9 September 1945', 85, 'https://en.wikipedia.org/wiki/Second_Sino-Japanese_War'),
  ('Q192055', 'Nanjing Massacre', 'The Nanjing Massacre or the Rape of Nanjing (formerly romanized as Nanking) was the mass rape and murder, between December 1937 and March 1938, of Chinese civilians, noncombatants, and prisoners of war by the Imperial Japanese Army in Nanjing, the capital of the Republic of China. It took place immediately after the Battle of Nanjing and retreat of the National Revolutionary Army during the Second Sino-Japanese War.', 1937, NULL, NULL, 1938, 2, 2, 'year', '1937 – 2 February 1938', 81, 'https://en.wikipedia.org/wiki/Nanjing_Massacre'),
  ('Q254599', 'Battle of Shanghai', 'The Battle of Shanghai (traditional Chinese: 淞滬會戰; simplified Chinese: 淞沪会战; pinyin: Sōng hù huìzhàn) was a major campaign fought between the Empire of Japan and the Republic of China in the Chinese city of Shanghai during the Second Sino-Japanese War. It lasted from August 13 to November 26, 1937, and was arguably the single largest and longest battle of the entire war, with it even regarded by some historians as the first battle of World War II. It resulted in the Japanese capture of Shanghai and heavy destruction to the city.', 1937, 8, 13, 1937, 11, 26, 'day', '13 August 1937 – 26 November 1937', 68, 'https://en.wikipedia.org/wiki/Battle_of_Shanghai'),
  ('Q362', 'World War II', 'World War II, or the Second World War (1 September 1939 – 2 September 1945), was a global conflict between two coalitions: the Allies and the Axis powers. Nearly all of the world''s countries were involved, with many engaging in total war on an unprecedented scale.', 1939, 9, 1, 1945, 9, 2, 'day', '1 September 1939 – 2 September 1945', 100, 'https://en.wikipedia.org/wiki/World_War_II'),
  ('Q665554', 'Japanese Instrument of Surrender', 'The Japanese Instrument of Surrender was the printed agreement that formalized the surrender of Japan, marking the end of hostilities in World War II. It was signed by representatives from Japan and from the Allied nations: the United States, China, the United Kingdom, the Soviet Union, Australia, Canada, France, the Netherlands, and New Zealand. The signing took place on the deck of USS Missouri in Tokyo Bay just after 09:00 Japan Standard Time (JST) and took effect at 09:25 JST on 2 September 1945.', 1945, 9, 2, NULL, NULL, NULL, 'day', '2 September 1945', 69, 'https://en.wikipedia.org/wiki/Japanese_Instrument_of_Surrender'),
  ('Q13578439', 'retrocession of Taiwan', 'On 25 October 1945, Japan handed over Taiwan and Penghu to the Republic of China, as a result of World War II. This marked the end of Japanese rule and the beginning of post-war era of Taiwan. This event was referred to by the Republic of China as the retrocession of Taiwan (臺灣光復).', 1945, 10, 25, NULL, NULL, NULL, 'day', '25 October 1945', 39, 'https://en.wikipedia.org/wiki/Retrocession_of_Taiwan'),
  ('Q179975', 'Chinese Civil War', 'The Chinese Civil War was fought between the government of the Republic of China (ROC), led by the Kuomintang (KMT), and the Chinese Communist Party (CCP). Armed conflict continued intermittently from 1 August 1927 until Communist victory that led to the Kuomintang''s retreat to Taiwan on 7 December 1949.', 1946, 3, 31, 1950, 5, 1, 'day', '31 March 1946 – 1 May 1950', 84, 'https://en.wikipedia.org/wiki/Chinese_Civil_War'),
  ('Q19840944', 'Treaty of Friendship, Commerce and Navigation between the United States of America and the Republic of China', 'The Treaty of Friendship, Commerce and Navigation between the United States of America and the Republic of China was a bilateral treaty signed by the United States and China on November 4, 1946. It became effective on November 30, 1948, following the mutual exchange of ratifications, pursuant to Article XXX. It fulfilled the desires of both countries to establish such a treaty as previously expressed in Article XII of the Treaty for Relinquishment of Extraterritorial Rights in China.', 1946, 11, 4, NULL, NULL, NULL, 'day', '4 November 1946', 37, 'https://en.wikipedia.org/wiki/Treaty_of_Friendship%2C_Commerce_and_Navigation_between_the_United_States_of_America_and_the_Republic_of_China'),
  ('Q244939', '228 Incident', 'The February 28 incident (also called the February 28 massacre, the 228 incident, or the 228 massacre) was an anti-government uprising in Taiwan in 1947 that was violently suppressed by the Kuomintang–led Nationalist government of the Republic of China (ROC). Directed by provincial governor Chen Yi and President Chiang Kai-shek, thousands of civilians were killed beginning on February 28.', 1947, 2, 27, 1947, 5, 16, 'day', '27 February 1947 – 16 May 1947', 68, 'https://en.wikipedia.org/wiki/February_28_incident'),
  ('Q7168624', 'Period of mobilization for the suppression of Communist rebellion', 'Period of mobilization for the suppression of Communist rebellion (Chinese: 動員戡亂時期; pinyin: Dòngyuán Kānluàn Shíqí; Pe̍h-ōe-jī: Tōng-oân Kham-loān sî-kî) is a political term used by the Kuomintang-led government of the Republic of China to indicate the country''s entering into a state of emergency with the raising Chinese Civil War. The term aimed to mobilize the people and resources under Kuomintang''s control to fight the Chinese Communist Party rebellion.', 1948, 5, 10, 1991, 5, 1, 'day', '10 May 1948 – 1 May 1991', 30, 'https://en.wikipedia.org/wiki/Period_of_mobilization_for_the_suppression_of_Communist_rebellion'),
  ('Q699096', 'Battle of Guningtou', 'The Battle of Guningtou (古寧頭之役), also known as the Battle of Kuningtou or the Battle of Kinmen (Chinese: 金門戰役), was fought in October 1949 on the island of Kinmen (Quemoy), located in the Taiwan Strait, during the final stages of the Chinese Civil War. The battle resulted in a decisive victory for the Republic of China (ROC, known today as Taiwan) forces and marked a significant turning point in the civil war.', 1949, NULL, NULL, 1949, 10, 27, 'year', '1949', 48, 'https://en.wikipedia.org/wiki/Battle_of_Guningtou'),
  ('Q7995467', 'White Terror (Taiwan)', 'The White Terror (Chinese: 白色恐怖; pinyin: Báisè Kǒngbù; Pe̍h-ōe-jī: Pe̍h-sek Khióng-pò͘) was the political repression of Taiwanese civilians and political dissenters under the government ruled by the Kuomintang (KMT). The period is generally considered to have begun when martial law was declared in Taiwan on 19 May 1949, which was enabled by the 1948 Temporary Provisions against the Communist Rebellion, and ended on 21 September 1992 with the repeal of Article 100 of the Criminal Code, allowing for the prosecution of "anti-state" activities.', 1949, 5, 19, 1992, 11, 6, 'day', '19 May 1949 – 6 November 1992', 57, 'https://en.wikipedia.org/wiki/White_Terror_(Taiwan)'),
  ('Q15896860', 'Yangtze River Crossing Campaign', 'The Yangtze River Crossing campaign (Chinese: 渡江战役) was a military campaign launched by the People''s Liberation Army to cross the Yangtze River and capture Nanjing, the capital of the Nationalist government of the Kuomintang, in the final stage of the Chinese Civil War. The campaign began at night on 20 April, and lasted until 2 June 1949, concluding after the fall of Nanjing and Shanghai to the Communist forces, which eventually resulted in the exile of the Nationalists to the island of Taiwan.', 1949, 4, 20, 1949, 6, 2, 'day', '20 April 1949 – 2 June 1949', 43, 'https://en.wikipedia.org/wiki/Yangtze_River_Crossing_campaign'),
  ('Q16165653', 'retreat of the government of Republic of China to Taiwan', 'The remnants of the government of the Republic of China (ROC), alongside many refugees, retreated to the island of Taiwan (Formosa) on December 7, 1949. The members of the Kuomintang (KMT), its officers, and approximately 2 million ROC troops took part in the retreat, in addition to many civilians and refugees, fleeing the advance of the People''s Liberation Army (PLA) of the Chinese Communist Party (CCP).', 1949, 12, 7, NULL, NULL, NULL, 'day', '7 December 1949', 55, 'https://en.wikipedia.org/wiki/Retreat_of_the_government_of_the_Republic_of_China_to_Taiwan'),
  ('Q707269', 'Treaty of Taipei', 'The Sino-Japanese Peace Treaty (Chinese: 中日和平條約; Japanese: 日華平和条約), formally the Treaty of Peace between the Republic of China and Japan (Chinese: 中華民國與日本國間和平條約; Japanese: 日本国と中華民国との間の平和条約) and commonly known as the Treaty of Taipei (Chinese: 臺北和約), was a peace treaty between Japan and the Republic of China (ROC) signed in Taipei, Taiwan on 28 April 1952, and took effect on August 5 the same year, marking the formal end of the Second Sino-Japanese War (1937–1945). Neither the Republic of China nor the People''s Republic of China was invited to sign the San Francisco Peace Treaty due to…', 1952, 4, 28, NULL, NULL, NULL, 'day', '28 April 1952', 55, 'https://en.wikipedia.org/wiki/Treaty_of_Taipei'),
  ('Q710193', 'Battle of Dachen Archipelago', 'The Battle of Dachen Archipelago (simplified Chinese: 大陈等岛之战; traditional Chinese: 大陳等島之戰; pinyin: Dàchén Děng Dǎo Zhī Zhàn) was fought between the Republic of China and the People''s Republic of China for the control of several archipelagos just off the coast of Zhejiang, China during the First Taiwan Strait Crisis. As the PLA targeted and heavily bombarded the islands, the Nationalist garrison''s infrastructure was destroyed, leaving them unable to adequately defend the archipelago.', 1955, 1, 19, 1955, 2, 26, 'day', '19 January 1955 – 26 February 1955', 34, 'https://en.wikipedia.org/wiki/Battle_of_Dachen_Archipelago'),
  ('Q2890719', 'Battle of Yijiangshan Islands', 'The Battle of Yijiangshan Islands occurred during the First Taiwan Strait Crisis in January 1955 when the People''s Republic of China (PRC) attacked and captured the islands from the Republic of China (ROC). The loss of the Yijiangshans forced the ROC to abandon the Dachen Islands to the PRC. The Chinese People''s Liberation Army (PLA) considers the battle as its first joint operation.', 1955, NULL, NULL, 1955, 1, 20, 'year', '1955', 45, 'https://en.wikipedia.org/wiki/Battle_of_Yijiangshan_Islands'),
  ('Q700442', 'Second Taiwan Strait Crisis', 'The Second Taiwan Strait Crisis, also known as the 1958 Taiwan Strait Crisis, was a conflict between the People''s Republic of China (PRC) and the Republic of China (ROC). The PRC shelled the islands of Kinmen (Quemoy) and the Matsu Islands along the east coast of mainland China in an attempt to take them from the ROC, governed by the Kuomintang (KMT), and to probe the extent of American commitment to defend the Republic of China.', 1958, 9, 22, 1958, 9, 22, 'day', '22 September 1958', 63, 'https://en.wikipedia.org/wiki/Second_Taiwan_Strait_Crisis'),
  ('Q708503', '1964 Baihe earthquake', 'The 1964 Baihe earthquake (Chinese: 1964年白河大地震; pinyin: 1964 nián Báihé dà dìzhèn), also known as the Great Baihe earthquake, measured 6.3 local magnitude, and occurred at 20:04 CST (UTC+8) on 18 January in Baihe Township of Tainan County (now part of Tainan City), Taiwan. The hypocenter of the earthquake was 20 kilometers deep.', 1964, 1, 18, NULL, NULL, NULL, 'day', '18 January 1964', 37, 'https://en.wikipedia.org/wiki/1964_Baihe_earthquake'),
  ('Q717780', 'Kaohsiung Incident', 'The Kaohsiung Incident, also known as the Formosa Incident, the Meilidao Incident, or the Formosa Magazine incident, was a crackdown on pro-democracy demonstrations that occurred in Kaohsiung, Taiwan, on 10 December 1979 during Taiwan''s martial law period. The incident occurred when Formosa Magazine, headed by released political prisoner Shih Ming-teh and veteran opposition legislator Huang Hsin-chieh, and other opposition politicians held a demonstration commemorating Human Rights Day to promote and demand democracy in Taiwan.', 1979, 12, 10, NULL, NULL, NULL, 'day', '10 December 1979', 43, 'https://en.wikipedia.org/wiki/Kaohsiung_Incident'),
  ('Q5942155', '1986 Hualien earthquake', 'The 1986 Hualien earthquake occurred on November 15, 1986, when a strong earthquake with a recorded magnitude of 7.4 struck Hualien City in Taiwan. The earthquake killed 15 people and injured 44.', 1986, 11, 15, NULL, NULL, NULL, 'day', '15 November 1986', 34, 'https://en.wikipedia.org/wiki/1986_Hualien_earthquake'),
  ('Q8000713', 'Wild Lily student movement', 'The Wild Lily student movement (Chinese: 野百合學運; pinyin: Yě Bǎihé xué yùn; Pe̍h-ōe-jī: Iá-pek-ha̍p ha̍k-ūn) or March student movement were a series of pro-democracy student demonstration in Taiwan which took place from 16-22 March 1990. The sit-in at Memorial Square in Taipei (since rededicated as Liberty Square in commemoration of the movement) was initiated by students from National Taiwan University.', 1990, NULL, NULL, NULL, NULL, NULL, 'year', '1990', 39, 'https://en.wikipedia.org/wiki/Wild_Lily_student_movement'),
  ('Q5968368', '1992 Taiwanese legislative election', 'Legislative elections were held in Taiwan on 19 December 1992.', 1992, 12, 19, NULL, NULL, NULL, 'day', '19 December 1992', 34, 'https://en.wikipedia.org/wiki/1992_Taiwanese_legislative_election'),
  ('Q10844109', '1994 Taiwanese provincial and municipal elections', 'Provincial and municipal elections were held in Taiwan on 3 December 1994, electing the Governor of Taiwan Province, and mayor of two special municipalities (Taipei and Kaohsiung). This is the first election for all three posts, and the only one for the governorship of the later-streamlined Taiwan Province.', 1994, 12, 3, NULL, NULL, NULL, 'day', '3 December 1994', 21, 'https://en.wikipedia.org/wiki/1994_Taiwanese_local_elections'),
  ('Q705373', 'Third Taiwan Strait Crisis', 'The Third Taiwan Strait Crisis, also called the 1995–1996 Taiwan Strait Crisis, or the 1996 Taiwan Strait Crisis, was the effect of a series of missile tests conducted by the People''s Republic of China (PRC) in the waters surrounding Taiwan, including the Taiwan Strait, from 21 July 1995 to 23 March 1996. The first set of missiles fired in mid-to-late 1995 was allegedly intended to send a strong signal to the Republic of China government (ROC) under President Lee Teng-hui, who had been seen as "moving its foreign policy away from the One-China policy", as claimed by the PRC. The second set…', 1995, 7, 21, 1996, 3, 23, 'day', '21 July 1995 – 23 March 1996', 61, 'https://en.wikipedia.org/wiki/Third_Taiwan_Strait_Crisis'),
  ('Q431657', '1996 Taiwanese presidential election', 'Presidential elections were held in Taiwan on 23 March 1996. It was Taiwan''s first direct presidential election, officially the Republic of China.', 1996, 3, 23, NULL, NULL, NULL, 'day', '23 March 1996', 53, 'https://en.wikipedia.org/wiki/1996_Taiwanese_presidential_election'),
  ('Q709416', 'China Airlines Flight 676', 'China Airlines Flight 676 was a scheduled international passenger flight. On 16 February 1998, the Airbus A300 jet airliner operating the flight crashed into a road and residential area in Tayuan, Taoyuan County (now Taoyuan City), near Chiang Kai-shek International Airport (now Taoyuan International Airport), Taiwan.', 1998, 2, 16, NULL, NULL, NULL, 'day', '16 February 1998', 58, 'https://en.wikipedia.org/wiki/China_Airlines_Flight_676'),
  ('Q714320', '1999 Jiji earthquake', 'The Chi-Chi earthquake (later also known as the Jiji earthquake, 921 Earthquake, or the great earthquake of September 21), was a 7.3 ML or 7.7 Mw earthquake which occurred in Jiji (Chi-Chi), Nantou County, Taiwan on September 21, 1999, at 01:47:12 local time. 2,415 people were killed, 11,305 injured, and NT$300 billion worth of damage was done.', 1999, 9, 21, NULL, NULL, NULL, 'day', '21 September 1999', 64, 'https://en.wikipedia.org/wiki/1999_Jiji_earthquake'),
  ('Q478172', 'Singapore Airlines Flight 006', 'Singapore Airlines Flight 006 was an international scheduled passenger flight from Singapore Changi Airport to Los Angeles International Airport, United States, via Chiang Kai-shek International Airport (now known as Taoyuan International Airport) near Taipei, Taiwan. On 31 October 2000, at 23:18 Taipei local time (14:18 UTC), the Boeing 747-400 operating the flight crashed into construction equipment during a typhoon.', 2000, 10, 31, NULL, NULL, NULL, 'day', '31 October 2000', 61, 'https://en.wikipedia.org/wiki/Singapore_Airlines_Flight_006'),
  ('Q710233', '2000 Taiwanese presidential election', 'Presidential elections were held in Taiwan on 18 March 2000 to elect the president and vice president. With a voter turnout of 83%, Chen Shui-bian and Annette Lu of the Democratic Progressive Party (DPP) were elected president and vice president respectively with a slight plurality.', 2000, 3, 18, NULL, NULL, NULL, 'day', '18 March 2000', 53, 'https://en.wikipedia.org/wiki/2000_Taiwanese_presidential_election'),
  ('Q435806', 'China Airlines Flight 611', 'China Airlines Flight 611 was a regularly scheduled international passenger flight operated by a Boeing 747-200 from Chiang Kai-shek International Airport (now Taoyuan International Airport) in Taiwan to Hong Kong International Airport. On May 25th, 2002, the flight disintegrated midair and crashed into the Taiwan Strait, 26 miles (23 nmi; 42 km) northeast of the Penghu Islands, 20 minutes after takeoff, killing all 225 people on board.', 2002, 5, 25, NULL, NULL, NULL, 'day', '25 May 2002', 64, 'https://en.wikipedia.org/wiki/China_Airlines_Flight_611'),
  ('Q698921', '2006 Hengchun earthquake', 'The 2006 Hengchun earthquakes occurred on December 26 at 20:26 and 20:34 local time off the southwest coast of Taiwan in the Luzon Strait, which connects the South China Sea with the Philippine Sea. The International Seismological Centre measured the shocks at 7.0 and 6.9 on the moment magnitude scale.', 2006, 12, 26, NULL, NULL, NULL, 'day', '26 December 2006', 56, 'https://en.wikipedia.org/wiki/2006_Hengchun_earthquakes'),
  ('Q707405', 'August 8 Flood', 'Typhoon Morakot, known in the Philippines as Typhoon Kiko, was the wettest and deadliest typhoon to impact Taiwan in recorded history. The eighth named storm and fourth typhoon of the 2009 Pacific typhoon season, Morakot wrought catastrophic damage in Taiwan, killing 755 people and leaving 26 people missing, and causing roughly NT$110 billion (US$3.3 billion) in damages.', 2009, 8, 6, 2009, 8, 10, 'day', '6 August 2009 – 10 August 2009', 34, 'https://en.wikipedia.org/wiki/Effects_of_Typhoon_Morakot_on_Taiwan'),
  ('Q708250', '2009 Hualien earthquake', 'The 2009 Hualien earthquake occurred on December 19 at 21:02:14 (local time) with a moment magnitude of 6.4 and a maximum Mercalli intensity of VI (Strong). The oblique-slip event took place off the coast of Hualien, Taiwan.', 2009, 12, 19, NULL, NULL, NULL, 'day', '19 December 2009', 34, 'https://en.wikipedia.org/wiki/2009_Hualien_earthquake'),
  ('Q2097061', '2010 Kaohsiung earthquakes', 'The 2010 Kaohsiung earthquake, measuring 6.3 Mw, occurred on March 4 at 08:18 a.m. local time.', 2010, 3, 4, NULL, NULL, NULL, 'day', '4 March 2010', 52, 'https://en.wikipedia.org/wiki/2010_Kaohsiung_earthquake'),
  ('Q8659209', 'March 2013 Nantou earthquake', 'The 2013 Nantou earthquake struck central Taiwan with a moment magnitude of 5.9 and a maximum Mercalli intensity of V (Moderate) on March 27 at 10:03 a.m. local time.', 2013, 3, 27, NULL, NULL, NULL, 'day', '27 March 2013', 34, 'https://en.wikipedia.org/wiki/March_2013_Nantou_earthquake'),
  ('Q13414773', 'June 2013 Nantou earthquake', 'The 2013 Nantou earthquake struck central Taiwan with a moment magnitude of 6.2 on 2 June at 1:43 p.m. local time.', 2013, 6, 2, NULL, NULL, NULL, 'day', '2 June 2013', 34, 'https://en.wikipedia.org/wiki/June_2013_Nantou_earthquake'),
  ('Q15972916', 'Sunflower Student Movement', 'The Sunflower Student Movement (Chinese: 太陽花學運) is associated with a protest movement driven by a coalition of students and civic groups that came to a head between March 18 and April 10, 2014, in the Legislative Yuan and later, the Executive Yuan of Taiwan. The activists protested the passage of the Cross-Strait Service Trade Agreement (CSSTA) by the then-ruling Kuomintang (KMT) at the legislature without a clause-by-clause review.', 2014, 3, 18, 2014, 4, 10, 'day', '18 March 2014 – 10 April 2014', 57, 'https://en.wikipedia.org/wiki/Sunflower_Student_Movement'),
  ('Q20441220', '2015 New Taipei water park explosion', 'On 27 June 2015, a dust fire occurred at Formosa Fun Coast, a water park in Bali, New Taipei City, Taiwan. Staff of an outdoor "color powder party" sprayed participants with clouds of corn starch, which ignited.', 2015, 6, 27, NULL, NULL, NULL, 'day', '27 June 2015', 43, 'https://en.wikipedia.org/wiki/2015_New_Taipei_water_park_fire'),
  ('Q22662663', '2016 Kaohsiung earthquake', 'At 03:57 local time on 6 February 2016, an earthquake with a moment magnitude of 6.4 struck 28 km (17 mi) northeast of Pingtung City in southern Taiwan, in the Meinong District of Kaohsiung. The earthquake struck at a depth of around 23 km (14 mi).', 2016, 2, 6, NULL, NULL, NULL, 'day', '6 February 2016', 66, 'https://en.wikipedia.org/wiki/2016_southern_Taiwan_earthquake'),
  ('Q47756250', '2018 Hualien earthquake', 'At 23:50 (UTC+8) on 6 February 2018, an earthquake of magnitude 6.4 on the moment magnitude scale hit Taiwan. The epicenter was on the coastline near Hualien, which was the most severely affected area, with a maximum felt intensity of 7 on the Central Weather Administration seismic intensity scale.', 2018, 2, 4, NULL, NULL, NULL, 'day', '4 February 2018', 58, 'https://en.wikipedia.org/wiki/2018_Hualien_earthquake'),
  ('Q55390763', 'Taiwanese same-sex marriage referendum', 'A multi-question referendum was held in Taiwan on 24 November 2018 alongside local elections. The referendum was the first since the December 2017 reform to the Referendum Act, which reduced the threshold for submitting questions to the ballot; under the new system, signatures from 1.5 percent of the electorate (around 280,000 people) were required to successfully put a question on the ballot, reduced from 5 percent previously.', 2018, 11, 24, NULL, NULL, NULL, 'day', '24 November 2018', 41, 'https://en.wikipedia.org/wiki/2018_Taiwanese_referendum'),
  ('Q63199418', '2019 Hualien earthquake', 'The 2019 Hualien earthquake (Chinese: 418花蓮地震) struck Hualien County, Taiwan with a moment magnitude of 6.1 on 18 April at 13:01 local time (05:01 UTC).', 2019, 4, 18, NULL, NULL, NULL, 'day', '18 April 2019', 39, 'https://en.wikipedia.org/wiki/2019_Hualien_earthquake'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q108887922', '2021 Kaohsiung tower fire', 'In the early morning hours of 14 October 2021, at 02:54 NST (UTC+8), a fire broke out in a 13-storey building at Fubei Road in Yancheng District, Kaohsiung, a city in southwestern Taiwan. At least 46 people were killed, and 41 others were injured.', 2021, 10, 14, NULL, NULL, NULL, 'day', '14 October 2021', 53, 'https://en.wikipedia.org/wiki/2021_Kaohsiung_building_fire'),
  ('Q114024810', 'September 2022 Taitung earthquakes', 'Two earthquakes affected Taitung and Hualien Counties, Taiwan within hours of each other. The first earthquake struck Taitung on September 17, 2022, occurring with a magnitude of 6.5 Mw, causing minor damage and some injuries.', 2022, 9, 18, NULL, NULL, NULL, 'day', '18 September 2022', 45, 'https://en.wikipedia.org/wiki/2022_Taitung_earthquakes'),
  ('Q125289722', '2024 Hualien earthquake', 'On 3 April 2024, at 07:58:11 NST (23:58:11 UTC on 2 April), a Mw 7.4 earthquake struck 15 km (9.3 mi) south of Hualien City, Hualien County, Taiwan., provience, The republic of China At least 19 people were killed and over 1,100 were injured in the earthquake. It was the strongest earthquake in Taiwan since the 1999 Jiji earthquake, with three aftershocks above Mw 6.0.', 2024, 4, 3, NULL, NULL, NULL, 'day', '3 April 2024', 72, 'https://en.wikipedia.org/wiki/2024_Hualien_earthquake'),
  ('Q131840654', '2025 Tainan–Chiayi earthquake', 'On 21 January 2025, at 00:17:26 TST (16:17 UTC on 20 January), a ML 6.4 (Mw 6.0) earthquake struck Dongshan District, Tainan City, Taiwan, near the border with Chiayi County. It was caused by reverse faulting and had a depth of 16 kilometres (9.9 miles).', 2025, 1, 21, NULL, NULL, NULL, 'day', '21 January 2025', 37, 'https://en.wikipedia.org/wiki/2025_Tainan%E2%80%93Chiayi_earthquake');
